SSCHCap03M7.value_unique {n : ℕ} [NeZero n] {P : Fin n → Fin n → ℝ} {r V W : Fin n → ℝ} {γ : ℝ}
  (hP : SSCHCap03M7.rowStoch P) (hγ0 : 0 ≤ γ) (hγ1 : γ < 1) (hV : ∀ (i : Fin n), V i = r i + γ * ∑ j, P i j * V j)
  (hW : ∀ (i : Fin n), W i = r i + γ * ∑ j, P i j * W j) : V = W

SSCHCap03M7.value_bound {n : ℕ} [NeZero n] {P : Fin n → Fin n → ℝ} {r V : Fin n → ℝ} {γ M : ℝ}
  (hP : SSCHCap03M7.rowStoch P) (hγ0 : 0 ≤ γ) (hγ1 : γ < 1) (hV : ∀ (i : Fin n), V i = r i + γ * ∑ j, P i j * V j)
  (hr : ∀ (i : Fin n), |r i| ≤ M) (i : Fin n) : |V i| ≤ M / (1 - γ)

SSCHCap03M7.viter_contract {n : ℕ} [NeZero n] {P : Fin n → Fin n → ℝ} {r V : Fin n → ℝ} {γ M : ℝ}
  (hP : SSCHCap03M7.rowStoch P) (hγ0 : 0 ≤ γ) (hγ1 : γ < 1) (hV : ∀ (i : Fin n), V i = r i + γ * ∑ j, P i j * V j)
  (hr : ∀ (i : Fin n), |r i| ≤ M) (k : ℕ) (i : Fin n) : |V i - SSCHCap03M7.viter P r γ k i| ≤ γ ^ k * (M / (1 - γ))

SSCHCap05M7.resolvent_formula {n : ℕ} {P : Fin n → Fin n → ℝ} {γ : ℝ} {A : (Fin n → ℝ) → Fin n → ℝ}
  (hA_id : ∀ (w : Fin n → ℝ), (A fun i => w i - γ * ∑ j, P i j * w j) = w)
  (hA_smul : ∀ (c : ℝ) (w : Fin n → ℝ), (A fun i => c * w i) = c • A w) {V dV : Fin n → ℝ} {dP : Fin n → Fin n → ℝ}
  (hdV : ∀ (i : Fin n), dV i = γ * ∑ j, P i j * dV j + γ * ∑ j, dP i j * V j) :
  dV = fun i => γ * A (fun i => ∑ j, dP i j * V j) i

∀ {Ω : Type u_1} {ι : Type u_2} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω} {l : Filter ι} {f : ι → Ω → ℝ}
  {g : Ω → ℝ},
  MeasureTheory.TendstoInMeasure μ f l g → MeasureTheory.TendstoInMeasure μ (fun i ω => -f i ω) l fun ω => -g ω
